$toolPages = @(
  @{file="brand-ambassador-contract.html"; title="Brand Ambassador Contract"; steps=@("Select the Brand Ambassador Contract template and enter your brand name, ambassador details, and campaign specifics.","Customize compensation structure, content requirements, exclusivity terms, and campaign duration.","Review the generated contract, then download as PDF or Word document for signing."); cases=@("<strong>Social media influencer partnerships</strong> - Brands hiring ambassadors for Instagram, TikTok, or YouTube campaigns with specific deliverable requirements.","<strong>Long-term brand representation</strong> - Companies engaging ambassadors for ongoing product promotion with exclusivity clauses and performance metrics.","<strong>Event-based ambassadorships</strong> - Businesses contracting ambassadors for trade shows, product launches, or promotional events with defined schedules."); faqs=@(@{q="What is the difference between a brand ambassador and an influencer contract?";a="A brand ambassador contract typically involves a longer-term, ongoing relationship where the ambassador represents the brand consistently. An influencer contract is usually project-based for specific campaigns or posts. Brand ambassador agreements often include exclusivity clauses preventing work with competitors."},@{q="Should I include social media metrics requirements in the contract?";a="Yes. Specify minimum posting frequency, required platforms, content approval processes, and performance benchmarks like engagement rates. This protects both parties by setting clear expectations for deliverables and compensation."},@{q="How do I handle product seeding in a brand ambassador contract?";a="Include a section detailing what products or services the brand will provide, whether they must be returned, and any restrictions on how gifted items can be used or discussed. Specify the retail value for tax reporting purposes."})},
  @{file="client-onboarding-contract.html"; title="Client Onboarding Contract"; steps=@("Choose the Client Onboarding Contract template and enter your business name and new client details.","Define onboarding milestones, deliverables, timelines, and responsibilities for both parties.","Generate the contract, review all terms, and download for client signature."); cases=@("<strong>Agency client onboarding</strong> - Marketing or design agencies establishing clear expectations, deliverables, and timelines when bringing on new clients.","<strong>SaaS implementation agreements</strong> - Software companies documenting setup, training, data migration, and go-live milestones for enterprise clients.","<strong>Consulting engagement kickoff</strong> - Consultants formalizing the onboarding process including discovery sessions, access requirements, and initial deliverables."); faqs=@(@{q="What should a client onboarding contract include?";a="A comprehensive onboarding contract should cover project scope, timeline with milestones, deliverables for each phase, client responsibilities (providing access, content, feedback), communication protocols, and criteria for completing the onboarding phase."},@{q="How long should the onboarding period be?";a="Onboarding periods vary by service complexity. Simple services may need 1-2 weeks, while enterprise software implementations or complex consulting engagements might require 30-90 days. Define clear milestones to track progress."},@{q="Can I charge separately for onboarding?";a="Yes. Many businesses charge a one-time onboarding or setup fee separate from recurring service fees. This covers the initial investment in understanding the client needs, configuring systems, and training their team."})},
  @{file="consulting-agreement.html"; title="Consulting Agreement"; steps=@("Select the Consulting Agreement template and enter consultant and client business details.","Specify the consulting scope, hourly or project rate, payment schedule, and engagement duration.","Review the agreement including confidentiality and IP clauses, then download for signatures."); cases=@("<strong>Management consulting engagements</strong> - Consultants providing strategic advice to businesses on operations, growth, or organizational restructuring.","<strong>IT and technology consulting</strong> - Tech consultants contracted for system audits, digital transformation planning, or technical architecture reviews.","<strong>Financial advisory services</strong> - Financial consultants engaged for business valuation, budgeting strategy, or investment planning projects."); faqs=@(@{q="What is the difference between a consulting agreement and a service agreement?";a="A consulting agreement focuses on providing expert advice, analysis, and recommendations. A service agreement covers the delivery of specific services or tangible outputs. Consulting agreements typically emphasize the consultant independent judgment and expertise rather than prescribed deliverables."},@{q="Should a consulting agreement specify hourly or project-based fees?";a="It depends on the engagement. Hourly rates work well for advisory roles with variable scope. Project-based fees are better for defined deliverables. Many consultants use a retainer model with a set number of hours per month for ongoing engagements."},@{q="How do I protect my consulting methodology?";a="Include an intellectual property clause that clearly states your pre-existing methodologies, frameworks, and tools remain your property. The client receives a license to use deliverables created for their project, but your underlying methods stay with you."})},
  @{file="copywriting-contract.html"; title="Copywriting Contract"; steps=@("Choose the Copywriting Contract template and enter your details as the copywriter along with client information.","Define the copywriting scope, number of revisions, word count, deadlines, and usage rights.","Generate and review the contract, then download it for both parties to sign."); cases=@("<strong>Website copy projects</strong> - Copywriters contracted to write homepage, about page, service pages, and landing page content for business websites.","<strong>Marketing campaign content</strong> - Creating ad copy, email sequences, social media captions, and sales funnel content for product launches.","<strong>SEO content writing</strong> - Producing blog posts, articles, and optimized web content with specific keyword targets and content calendars."); faqs=@(@{q="How many revisions should I include in a copywriting contract?";a="Industry standard is 2-3 rounds of revisions included in the base price. Clearly define what constitutes a revision versus a new direction. Additional revisions beyond the included rounds should be billed at an hourly rate specified in the contract."},@{q="Who owns the copyright to the written content?";a="Typically, copyright transfers to the client upon full payment. However, the copywriter may retain the right to display the work in their portfolio. Specify these terms clearly, including whether the transfer includes all drafts or only final approved content."},@{q="Should I include a kill fee in my copywriting contract?";a="Yes. A kill fee (typically 25-50% of the total project fee) protects you if the client cancels the project after work has begun. This compensates for time invested and the opportunity cost of turning down other projects."})},
  @{file="freelance-contract.html"; title="Freelance Contract"; steps=@("Select the Freelance Contract template and enter both client and contractor details including names and contact information.","Customize the project scope, payment terms, timeline, and intellectual property transfer clauses.","Review the complete contract, make any adjustments, and download as PDF or Word for signing."); cases=@("<strong>Web development projects</strong> - Freelance developers contracting with clients for website builds, app development, or software customization projects.","<strong>Creative design work</strong> - Freelance designers establishing terms for branding, illustration, UI/UX design, or print material creation.","<strong>Writing and content creation</strong> - Freelance writers setting clear terms for blog posts, technical writing, ghostwriting, or content strategy projects."); faqs=@(@{q="What payment structure works best for freelance contracts?";a="A milestone-based structure is recommended: 25-50% upfront deposit, payments at defined milestones, and final payment on delivery. This protects both parties and ensures cash flow for the freelancer while giving the client checkpoints."},@{q="How should I handle scope creep in a freelance contract?";a="Include a change order clause that requires any work beyond the original scope to be documented in writing with adjusted pricing and timelines. This prevents misunderstandings and ensures you are compensated for additional work."},@{q="Do I need a separate NDA with my freelance contract?";a="The freelance contract template includes a basic confidentiality clause. For projects involving sensitive business information, trade secrets, or proprietary technology, consider using a separate, more detailed NDA in addition to the freelance contract."})},
  @{file="graphic-design-contract.html"; title="Graphic Design Contract"; steps=@("Choose the Graphic Design Contract template and fill in designer and client business details.","Specify design deliverables, revision rounds, file formats, timeline, and usage rights.","Review all terms including intellectual property transfer, then download for signing."); cases=@("<strong>Brand identity projects</strong> - Designers creating logos, brand guidelines, color palettes, and visual identity systems for new or rebranding businesses.","<strong>Marketing collateral design</strong> - Creating brochures, flyers, business cards, banners, and other print or digital marketing materials.","<strong>Packaging design</strong> - Product packaging design projects including label design, box design, and production-ready artwork files."); faqs=@(@{q="What file formats should a graphic design contract specify?";a="Specify all deliverable formats upfront. Common formats include AI or PSD source files, PDF for print, PNG and SVG for web, and JPEG for general use. Source files are often delivered only upon full payment as leverage for final payment."},@{q="How do I price design revisions?";a="Include 2-3 revision rounds in your base price. Define what counts as a revision (minor adjustments) versus a new concept (starting over). Additional revisions beyond the included rounds should be billed at your hourly rate, stated clearly in the contract."},@{q="Should the contract address stock images and fonts?";a="Yes. Specify whether stock images and commercial fonts are included in the project fee or billed separately. Clarify licensing responsibilities ensuring the client has proper licenses for all assets used in the final deliverables."})},
  @{file="independent-contractor.html"; title="Independent Contractor Agreement"; steps=@("Select the Independent Contractor Agreement template and enter hiring company and contractor details.","Define the scope of work, compensation structure, contractor status provisions, and term of engagement.","Review the agreement ensuring proper independent contractor classification, then download for signatures."); cases=@("<strong>Hiring specialized professionals</strong> - Businesses engaging independent specialists for specific projects without creating an employment relationship.","<strong>Ongoing contractor relationships</strong> - Companies working with regular contractors who maintain their independent business status while providing consistent services.","<strong>Cross-border contractor engagements</strong> - Hiring contractors in different states or countries with proper tax classification and legal compliance."); faqs=@(@{q="What is the difference between an independent contractor and an employee?";a="Independent contractors control how, when, and where they work. They use their own tools, can work for multiple clients, and handle their own taxes. Employees work under the employer direction, use company resources, and receive benefits. Misclassification can result in significant tax penalties and legal liability."},@{q="What tax forms are needed for independent contractors?";a="In the US, the hiring company must collect a W-9 form from the contractor and issue a 1099-NEC if payments exceed 600 dollars in a calendar year. The contractor is responsible for self-employment taxes and quarterly estimated tax payments."},@{q="Can an independent contractor agreement include non-compete clauses?";a="Non-compete clauses for independent contractors are increasingly restricted by law in many jurisdictions. While you can include reasonable non-solicitation clauses, overly broad non-compete terms may be unenforceable and could actually suggest an employment relationship."})},
  @{file="influencer-contract.html"; title="Influencer Contract"; steps=@("Choose the Influencer Contract template and enter brand and influencer details including social platforms.","Customize content requirements, posting schedule, compensation, usage rights, and FTC disclosure terms.","Review the complete agreement and download for both parties to review and sign."); cases=@("<strong>Sponsored content campaigns</strong> - Brands contracting influencers for Instagram posts, YouTube videos, or TikTok content featuring their products or services.","<strong>Affiliate marketing partnerships</strong> - Setting up commission-based arrangements where influencers promote products with tracked links and performance-based compensation.","<strong>Product review and unboxing</strong> - Brands sending products to influencers for honest review content with specific deliverable and timeline requirements."); faqs=@(@{q="What FTC disclosure requirements should be in an influencer contract?";a="The contract must require the influencer to clearly disclose the sponsored nature of all content using hashtags like #ad or #sponsored. FTC guidelines require disclosures to be clear, conspicuous, and in the same medium as the endorsement. Non-compliance can result in fines for both the brand and influencer."},@{q="How should content approval work in an influencer contract?";a="Specify a content approval workflow: influencer submits draft content, brand has 24-48 hours to review, and define the number of revision requests allowed. Balance brand control with the influencer authentic voice, which is what makes influencer marketing effective."},@{q="Should influencer contracts include exclusivity clauses?";a="Exclusivity clauses prevent influencers from promoting competing brands during the campaign period. If included, the exclusivity period should be clearly defined and the compensation should reflect this restriction, as it limits the influencer earning potential."})},
  @{file="invoice-template.html"; title="Invoice Template"; steps=@("Select the Invoice Template and enter your business details including name, address, and payment information.","Add line items with descriptions, quantities, rates, and any applicable taxes or discounts.","Generate a professional invoice and download as PDF to send to your client."); cases=@("<strong>Freelance project billing</strong> - Freelancers creating professional invoices for completed projects with itemized services, payment terms, and bank details.","<strong>Recurring service invoicing</strong> - Service providers generating monthly or quarterly invoices for ongoing retainer clients with consistent formatting.","<strong>Milestone payment requests</strong> - Contractors invoicing for specific project milestones as defined in their service agreements or contracts."); faqs=@(@{q="What information must be included on a professional invoice?";a="A professional invoice should include: your business name and contact info, client details, unique invoice number, issue date, payment due date, itemized list of services with rates, subtotal, applicable taxes, total amount due, and accepted payment methods."},@{q="What payment terms should I set on my invoice?";a="Common payment terms include Net 15 (payment due in 15 days), Net 30 (30 days), or Due on Receipt. For new clients, shorter terms like Net 15 or a deposit requirement reduce payment risk. Always include late payment fee terms to incentivize timely payment."},@{q="How do I handle unpaid invoices?";a="Start with a polite reminder at the due date. Follow up with a formal past-due notice including late fees as specified in your contract. If payment remains outstanding after 60-90 days, consider a final demand letter before pursuing collections or small claims court."})},
  @{file="logo-design-contract.html"; title="Logo Design Contract"; steps=@("Choose the Logo Design Contract template and enter designer and client business information.","Define the number of initial concepts, revision rounds, final file formats, and usage rights.","Review intellectual property and transfer clauses, then download the contract for signing."); cases=@("<strong>Startup branding</strong> - New businesses commissioning a professional logo as the foundation of their brand identity and marketing materials.","<strong>Corporate rebranding</strong> - Established companies hiring designers for logo redesign projects with brand guidelines and rollout specifications.","<strong>Logo design contests</strong> - Formalizing the terms when selecting a winning design from multiple concepts or designers with clear ownership transfer."); faqs=@(@{q="How many logo concepts should be included?";a="Industry standard is 3-5 initial concepts. The contract should clearly state the number of concepts included in the base price, with additional concepts available at a specified extra fee. This sets clear expectations and prevents unlimited concept requests."},@{q="When does logo ownership transfer to the client?";a="Ownership transfers upon full payment unless otherwise specified. Until payment is complete, the designer retains all rights. The contract should specify whether the client receives source files (AI, EPS) or only web-ready formats, and whether previous concepts remain the designer property."},@{q="Should the contract cover logo usage guidelines?";a="Yes. Include whether the designer will provide a basic brand guide with the logo (minimum sizes, clear space, color codes, acceptable backgrounds). A comprehensive brand guidelines document is usually a separate deliverable with additional cost."})},
  @{file="music-producer-contract.html"; title="Music Producer Contract"; steps=@("Select the Music Producer Contract template and enter producer and artist details.","Specify beat/track details, royalty splits, master ownership, credit requirements, and delivery format.","Review all terms including publishing rights and royalties, then download for signing."); cases=@("<strong>Beat licensing agreements</strong> - Producers licensing beats to recording artists with specific terms for exclusive or non-exclusive usage rights.","<strong>Full production deals</strong> - Producers contracted to produce entire albums or EPs with defined royalty splits, advance payments, and credit terms.","<strong>Work-for-hire production</strong> - Producers creating custom music for commercials, films, or media projects where the client retains full ownership."); faqs=@(@{q="What is the difference between exclusive and non-exclusive beat licenses?";a="An exclusive license grants sole usage rights to one artist, the producer cannot sell that beat to anyone else. Non-exclusive licenses allow the producer to sell the same beat to multiple artists. Exclusive licenses command significantly higher fees and should clearly define the scope of rights transferred."},@{q="How should royalties be structured in a producer contract?";a="Standard industry practice is 3-5 percent of retail for album sales, though this varies. Specify whether royalties are based on gross or net revenue, define accounting periods, and include audit rights. For streaming, define how streaming royalties are calculated and split."},@{q="Should the contract address sample clearance?";a="Yes. Specify who is responsible for identifying and clearing any samples used in the production. Typically, the producer must disclose all samples and the party requesting specific samples handles clearance costs. Uncleared samples can result in significant legal liability."})},
  @{file="nda-generator.html"; title="NDA Generator"; steps=@("Select the NDA Generator template and choose between mutual (two-way) or unilateral (one-way) protection.","Enter the disclosing and receiving party details, define confidential information categories, and set the agreement duration.","Review the NDA terms including exclusions and remedies, then download for signing."); cases=@("<strong>Business partnership discussions</strong> - Protecting sensitive information during merger talks, joint venture planning, or strategic partnership negotiations.","<strong>Employee and contractor onboarding</strong> - Requiring new team members to sign NDAs before accessing proprietary processes, client lists, or trade secrets.","<strong>Investor pitches and fundraising</strong> - Protecting business plans, financial projections, and proprietary technology details shared during fundraising presentations."); faqs=@(@{q="What is the difference between a mutual and unilateral NDA?";a="A mutual (bilateral) NDA protects both parties confidential information equally. A unilateral (one-way) NDA protects only one party information. Use mutual NDAs for partnerships and collaborations. Use unilateral NDAs when only one party is sharing sensitive information, such as employer-employee relationships."},@{q="How long should an NDA last?";a="NDA terms typically range from 1-5 years, with 2-3 years being most common. Trade secrets may warrant indefinite protection. The duration should be reasonable for the type of information protected. Overly long terms may be challenged as unreasonable in court."},@{q="What information can be excluded from an NDA?";a="Standard exclusions include: information already publicly available, information the receiving party already knew, information independently developed without reference to confidential materials, and information received from a third party without confidentiality obligations. These exclusions are important for enforceability."})},
  @{file="photography-contract.html"; title="Photography Contract"; steps=@("Choose the Photography Contract template and enter photographer and client details including event or project information.","Customize session details, deliverables, editing style, usage rights, and cancellation policy.","Review all terms and download the contract for client review and signature."); cases=@("<strong>Wedding and event photography</strong> - Professional photographers documenting weddings, corporate events, or special occasions with defined deliverables and timelines.","<strong>Commercial product photography</strong> - Brands hiring photographers for e-commerce product shots, catalog images, or advertising campaign visuals.","<strong>Portrait and family sessions</strong> - Photographers booking portrait sessions with clear terms for retouching, print rights, and digital file delivery."); faqs=@(@{q="What usage rights should a photography contract specify?";a="Define whether the client receives personal use only, commercial use, or full unrestricted rights. Specify permitted uses such as social media, print, advertising, and web. The photographer typically retains copyright and grants a license. Full copyright transfer commands a premium and should be explicitly stated."},@{q="How should cancellation and rescheduling be handled?";a="Include a tiered cancellation policy: full refund 30+ days before, 50% refund 15-30 days, no refund within 14 days. For rescheduling, allow one free reschedule with adequate notice. Retainer or deposit amounts should be clearly stated as non-refundable."},@{q="Should the contract cover model releases?";a="Yes. If photographs include identifiable people, specify who is responsible for obtaining model releases. For commercial use, model releases are essential. The contract should clarify whether the photographer can use images for portfolio, social media, or marketing purposes."})},
  @{file="service-agreement.html"; title="Service Agreement"; steps=@("Select the Service Agreement template and enter service provider and client business details.","Define the services to be provided, pricing structure, service level expectations, and contract duration.","Review the complete agreement including termination and liability terms, then download for signatures."); cases=@("<strong>Managed IT services</strong> - IT companies documenting service levels, response times, and support terms for ongoing technology management contracts.","<strong>Marketing agency retainers</strong> - Agencies establishing monthly service terms, deliverable lists, and performance reporting for retained clients.","<strong>Maintenance and support contracts</strong> - Service providers formalizing ongoing maintenance, repair, or support arrangements with recurring billing terms."); faqs=@(@{q="What is the difference between a service agreement and a contract?";a="Technically, a service agreement is a type of contract. In practice, service agreements tend to focus on ongoing or recurring services with defined service levels, while contracts often cover one-time projects with specific deliverables. Both are legally binding when properly executed."},@{q="Should a service agreement include SLAs?";a="Yes, for professional services. Service Level Agreements (SLAs) define measurable performance standards like response times, uptime guarantees, and resolution timeframes. Include consequences for missing SLAs and procedures for reporting and tracking service issues."},@{q="How do I handle price increases in a service agreement?";a="Include a clause allowing price adjustments with 30-60 days written notice. Specify whether annual increases are tied to inflation, a fixed percentage, or market rates. Give the client the right to terminate if they do not accept the new pricing."})},
  @{file="social-media-contract.html"; title="Social Media Management Contract"; steps=@("Choose the Social Media Management Contract template and enter your agency or freelancer details along with client information.","Define platforms to manage, posting frequency, content types, reporting schedule, and ad budget management terms.","Review the contract including content ownership and approval workflow, then download for signing."); cases=@("<strong>Small business social media management</strong> - Agencies or freelancers taking over daily social media operations for local businesses or startups.","<strong>Corporate social media strategy</strong> - Social media managers contracted for enterprise-level accounts with multiple platforms, team coordination, and crisis management protocols.","<strong>Social media content creation</strong> - Content creators contracted specifically for producing photos, videos, graphics, and captions for client social channels."); faqs=@(@{q="What platforms should be specified in a social media contract?";a="List every platform you will manage (Instagram, Facebook, LinkedIn, TikTok, Twitter/X, Pinterest, YouTube). Specify the number of posts per platform per week, content types (images, videos, stories, reels), and whether the contract covers paid advertising management."},@{q="Who owns the social media content created?";a="Typically, content created for the client social media accounts transfers to the client upon payment. However, the social media manager often retains the right to use content in their portfolio. Clarify ownership of templates, brand assets, and content calendars."},@{q="How should social media reporting be handled?";a="Define monthly reporting requirements including metrics to track (engagement rate, follower growth, reach, conversions), reporting format, and delivery timeline. Specify whether strategy recommendations are included and how often performance review meetings occur."})},
  @{file="video-editing-contract.html"; title="Video Editing Contract"; steps=@("Select the Video Editing Contract template and enter editor and client details.","Specify project scope, number of videos, revision rounds, delivery formats, and timeline.","Review terms including raw footage handling and usage rights, then download for signing."); cases=@("<strong>YouTube content editing</strong> - Video editors contracted to edit, color grade, and add graphics to YouTube videos on a per-video or retainer basis.","<strong>Corporate video production</strong> - Editors hired for training videos, promotional content, or internal communications with specific brand guidelines.","<strong>Wedding and event video editing</strong> - Post-production editing of ceremony footage, highlight reels, and social media cuts from event recordings."); faqs=@(@{q="How many revision rounds should a video editing contract include?";a="Standard practice is 2-3 rounds of revisions. The first round addresses major structural changes, the second covers fine-tuning, and a third handles final polish. Define what constitutes a revision versus a new edit direction to prevent scope creep."},@{q="Who provides the music and sound effects?";a="Specify whether the editor sources royalty-free music (and whether licensing costs are included in the fee) or whether the client provides licensed music. Using unlicensed music can result in copyright strikes and legal issues, so clarity here is essential."},@{q="How should raw footage and project files be handled?";a="Define how long the editor will retain raw footage and project files after delivery (typically 30-90 days). Specify whether project files (Premiere, DaVinci Resolve, After Effects) are included in the deliverables or available for an additional fee."})},
  @{file="videography-contract.html"; title="Videography Contract"; steps=@("Choose the Videography Contract template and enter videographer and client details.","Define shoot details, equipment provisions, deliverables, editing terms, and usage rights.","Review the complete contract including cancellation and force majeure clauses, then download."); cases=@("<strong>Event videography</strong> - Professional videographers hired to capture weddings, conferences, concerts, or corporate events with defined deliverable packages.","<strong>Commercial video production</strong> - Businesses commissioning promotional videos, TV commercials, or social media video content with specific creative briefs.","<strong>Documentary filming</strong> - Videographers contracted for documentary projects with multi-day shoots, interview filming, and extended post-production timelines."); faqs=@(@{q="What equipment provisions should be in a videography contract?";a="Specify who provides cameras, lighting, audio equipment, and any specialized gear (drones, gimbals, monitors). If the videographer provides equipment, include insurance requirements. Equipment rental fees should be listed separately if not included in the production fee."},@{q="How should drone footage be addressed?";a="If drone footage is required, specify FAA Part 107 certification compliance (in the US), insurance requirements for drone operations, and any location-specific permits needed. Drone footage should be listed as a separate deliverable with its own pricing."},@{q="What delivery formats should be specified?";a="Common delivery formats include MP4 (H.264 or H.265) for web, ProRes for broadcast quality, and specific resolutions (1080p, 4K). Specify frame rates, color space, and whether the client receives both a final edited version and raw footage."})},
  @{file="virtual-assistant-contract.html"; title="Virtual Assistant Contract"; steps=@("Select the Virtual Assistant Contract template and enter your business details and virtual assistant information.","Define tasks and responsibilities, working hours, communication tools, confidentiality terms, and compensation.","Review all clauses and download the contract for both parties to sign."); cases=@("<strong>Administrative support</strong> - Hiring a VA for email management, calendar scheduling, travel booking, and general administrative tasks with defined weekly hours.","<strong>E-commerce support</strong> - VAs contracted to handle customer service, order processing, inventory management, and product listing updates for online stores.","<strong>Executive assistant services</strong> - Senior-level virtual assistants supporting executives with meeting coordination, document preparation, and project management."); faqs=@(@{q="How should working hours be defined for a virtual assistant?";a="Specify the number of hours per week or month, expected availability windows (considering time zones), and whether unused hours roll over. Define overtime rates and the process for requesting additional hours beyond the contracted amount."},@{q="What confidentiality protections are needed for virtual assistants?";a="VAs often access sensitive business information including email accounts, financial records, and client data. Include strong confidentiality clauses, data handling procedures, and requirements for secure password management. Require return or destruction of all data upon contract termination."},@{q="Should the contract specify tools and software?";a="Yes. List required tools (Slack, Asana, Google Workspace, etc.) and specify who provides licenses and access. Define data backup responsibilities and whether the VA can use personal devices or must use specified secure systems."})},
  @{file="web-design-contract.html"; title="Web Design Contract"; steps=@("Choose the Web Design Contract template and enter designer/agency and client business details.","Define the website scope, pages, features, design revisions, hosting arrangements, and launch timeline.","Review the contract including post-launch support terms, then download for signing."); cases=@("<strong>Business website redesign</strong> - Companies hiring designers for complete website overhauls including UX research, wireframes, visual design, and development.","<strong>E-commerce website build</strong> - Creating online stores with product catalogs, payment integration, shipping calculators, and inventory management features.","<strong>Landing page design</strong> - Marketing teams commissioning high-converting landing pages for specific campaigns, product launches, or lead generation."); faqs=@(@{q="What should a web design contract say about hosting?";a="Specify whether hosting is included in the project fee or a separate monthly cost. Define who owns the hosting account, server requirements, uptime guarantees, and what happens to hosting if the contract ends. Clarify whether the client can transfer their site to a different host."},@{q="How should content responsibility be handled?";a="Clearly state who provides website content (copy, images, videos). If the designer writes content, specify word counts and revision rounds. Set deadlines for client-provided content and include a clause stating that delays in content delivery will delay the project timeline."},@{q="What about post-launch maintenance and updates?";a="Define a support period after launch (typically 30 days for bug fixes). For ongoing maintenance, specify a separate retainer or hourly rate for updates, security patches, and content changes. Clarify what is covered under warranty versus billable maintenance."})},
  @{file="website-maintenance-contract.html"; title="Website Maintenance Contract"; steps=@("Select the Website Maintenance Contract template and enter service provider and website owner details.","Define maintenance services, update frequency, response times, backup procedures, and monthly fee.","Review SLA terms and support scope, then download the contract for signing."); cases=@("<strong>WordPress maintenance plans</strong> - Developers offering monthly WordPress core, theme, and plugin updates with security monitoring and backup services.","<strong>E-commerce site maintenance</strong> - Ongoing technical support for online stores including product updates, payment system maintenance, and performance optimization.","<strong>Corporate website support</strong> - IT teams or agencies providing continuous website monitoring, content updates, and technical support for business websites."); faqs=@(@{q="What should website maintenance include?";a="Essential maintenance tasks include: CMS and plugin updates, security monitoring and malware scanning, regular backups, uptime monitoring, performance optimization, SSL certificate management, and basic content updates. Define which tasks are included in the base fee and which incur additional charges."},@{q="How often should maintenance tasks be performed?";a="Security updates should be applied within 24-48 hours of release. Regular maintenance (backups, performance checks, analytics review) should be weekly or monthly. Content updates depend on the client needs. Define all frequencies clearly in the contract."},@{q="What happens if the website goes down?";a="Define response time SLAs for different severity levels: critical outage (1-2 hour response), functionality issues (4-8 hours), and minor issues (24-48 hours). Specify communication procedures during outages and whether emergency support outside business hours is included or billed separately."})}
)

$basePath = "C:\Users\Administrator\contractfixpro"

foreach ($page in $toolPages) {
    $filePath = Join-Path $basePath $page.file
    $content = [System.IO.File]::ReadAllText($filePath, [System.Text.Encoding]::UTF8)

    if ($content -match 'tool-content-modules') {
        Write-Output "SKIP: $($page.file)"
        continue
    }

    # Add CSS link
    if ($content -notmatch 'tool-modules\.css') {
        $content = $content -replace '</head>', "<link rel=`"stylesheet`" href=`"/assets/css/tool-modules.css`">`n</head>"
    }

    # Build module HTML
    $stepsHtml = ($page.steps | ForEach-Object { "      <li>$_</li>" }) -join "`n"
    $casesHtml = ($page.cases | ForEach-Object { "      <li>$_</li>" }) -join "`n"
    $faqItems = @()
    foreach ($faq in $page.faqs) {
        $faqItems += "    <div class=`"tool-faq-item`">`n      <div class=`"tool-faq-q`">$($faq.q)</div>`n      <p class=`"tool-faq-a`">$($faq.a)</p>`n    </div>"
    }
    $faqsHtml = $faqItems -join "`n"

    $moduleHtml = @"

<!-- tool-content-modules -->
<div class="tool-content-modules">
  <div class="tool-info-card">
    <h2 class="tool-info-title">How to Use This $($page.title)</h2>
    <ol class="tool-steps">
$stepsHtml
    </ol>
  </div>
  <div class="tool-info-card">
    <h2 class="tool-info-title">Common Use Cases</h2>
    <ul class="tool-use-cases">
$casesHtml
    </ul>
  </div>
  <div class="tool-info-card">
    <h2 class="tool-info-title">Frequently Asked Questions</h2>
    <div class="tool-faq">
$faqsHtml
    </div>
  </div>
</div>
"@

    $content = $content -replace '</main>', "$moduleHtml`n</main>"
    [System.IO.File]::WriteAllText($filePath, $content, [System.Text.Encoding]::UTF8)
    Write-Output "DONE: $($page.file)"
}
